// lucide.min.js — 影子系统本地 Lucide 矢量图标代理按需加载模块
(function() {
  console.log("Lucide Proxy: Bootstrapping full vector engine from CDN...");
  
  const script = document.createElement('script');
  // Load from official unpkg mirror
  script.src = "https://unpkg.com/lucide@0.453.0/dist/umd/lucide.min.js";
  
  script.onload = function() {
    console.log("Lucide Proxy: Vector engine compiled and loaded successfully.");
    // Expose namespace globally
    window.lucide = window.lucide || lucide;
    
    // Auto sweep DOM once to dress icon slots immediately
    try {
      lucide.createIcons();
    } catch (e) {
      console.warn("Lucide Proxy auto-sweep exception:", e);
    }
  };
  
  script.onerror = function() {
    console.error("Lucide Proxy: Engine failed to load from primary mirror.");
  };
  
  document.head.appendChild(script);
})();
